import React, { useState, useEffect } from "react";
import axios from "axios";
import Menu from "./Menu";

const TopBar = () => {
  const [nifty, setNifty] = useState(0);
  const [sensex, setSensex] = useState(0);
  const [niftyChange, setNiftyChange] = useState("");
  const [sensexChange, setSensexChange] = useState("");

  const fetchMarketData = async () => {
    const options = {
      method: 'GET',
      url: 'https://yahoo-finance1.p.rapidapi.com/market/get-quotes',
      params: { symbols: '^BSESN,^NSEI' },
      headers: {
        'X-RapidAPI-Key': '18e22b5c80msh4adb5a8621351a2p1a5231jsn1856e118763b', // Aapki key yahan hai
        'X-RapidAPI-Host': 'yahoo-finance1.p.rapidapi.com'
      }
    };

    try {
      const response = await axios.request(options);
      const data = response.data.quotes;

      // Nifty Data Update
      const nData = data.find(item => item.symbol === '^NSEI');
      if (nData) {
        setNifty(nData.regularMarketPrice.toFixed(2));
        setNiftyChange(nData.regularMarketChangePercent.toFixed(2));
      }

      // Sensex Data Update
      const sData = data.find(item => item.symbol === '^BSESN');
      if (sData) {
        setSensex(sData.regularMarketPrice.toFixed(2));
        setSensexChange(sData.regularMarketChangePercent.toFixed(2));
      }
    } catch (error) {
      console.error("Market Data Fetch Error:", error);
    }
  };

  useEffect(() => {
    fetchMarketData(); // Pehli baar load hone par
    const interval = setInterval(fetchMarketData, 15000); // Har 15 second mein update (API limit bachane ke liye)
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="topbar-container">
      <div className="indices-container">
        <div className="nifty">
          <p className="index">NIFTY 50</p>
          <p className="index-points" style={{ color: niftyChange >= 0 ? "#4caf50" : "#df514c" }}>
            {nifty || "Loading..."}
          </p>
          <p className="percent" style={{ color: niftyChange >= 0 ? "#4caf50" : "#df514c" }}>
            {niftyChange}%
          </p>
        </div>
        <div className="sensex">
          <p className="index">SENSEX</p>
          <p className="index-points" style={{ color: sensexChange >= 0 ? "#4caf50" : "#df514c" }}>
            {sensex || "Loading..."}
          </p>
          <p className="percent" style={{ color: sensexChange >= 0 ? "#4caf50" : "#df514c" }}>
            {sensexChange}%
          </p>
        </div>
      </div>

      <Menu />
    </div>
  );
};

export default TopBar;
